    // «الزوجة السابقة» يجعل مطلَّقةَ أخيك مطلَّقتَك أنت.
    const fallbackKey = relationKey === "ex_spouse" ? "spouse" : relationKey;
    const byAnchor = RELATIVE_KINSHIP_MAP[anchorKinship];
    const pick = (map, k) => (map && map[k] && map[k][g]) || null;
